template <bool B>
inline bool VerifyCtrlMsg(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, CtrlMsg type) {
  switch (type) {
    case CtrlMsg::NONE: {
      return true;
    }
    case CtrlMsg::Hello: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::Hello *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::Welcome: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::Welcome *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::CapsSnapshot: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::CapsSnapshot *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::SurfaceOp: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::SurfaceOp *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::SurfaceReply: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::SurfaceReply *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::ResyncRequest: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::ResyncRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::ResyncDone: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::ResyncDone *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::AuxRequest: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::AuxRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::Fatal: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::Fatal *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CtrlMsg::LogLine: {
      auto ptr = reinterpret_cast<const MobileGL::Wire::LogLine *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyCtrlMsgVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<CtrlMsg> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyCtrlMsg(
        verifier,  values->Get(i), types->GetEnum<CtrlMsg>(i))) {
      return false;
    }
  }
  return true;
}

